console.log(`Total: $${(cents / 100).toFixed(2)}`);

steps.body:
Awaiting one call after another adds up their waits. When the calls don't depend on each other, start them all and wait once. `Promise.all` takes an array of promises and resolves to their values, in the same order. Given an array literal, TypeScript types the result as a tuple, with one type per position:

```typescript
import { setTimeout as sleep } from "node:timers/promises";

const [count, unit] = await Promise.all([sleep(20, 3), sleep(10, "items")]);
//     ^? const count: number
console.log(`${count} ${unit}`); // 3 items
```

`sleep(ms, value)` resolves with `value`, so these two promises hold a `number` and a `string`.

`Promise.all` rejects as soon as one promise rejects. `Promise.allSettled` waits for every promise and never rejects. Each of its results has a `status` of `"fulfilled"` with a `value`, or `"rejected"` with a `reason`, so checking `status` narrows a result like any tagged union. `Promise.race` settles like the first promise to settle, success or failure, while `Promise.any` resolves with the first success.

examples.code:
import { setTimeout as sleep } from "node:timers/promises";

type User = { id: number; name: string };
type Order = { id: string; userId: number; totalCents: number };

async function loadUser(id: number): Promise<User> {
  await sleep(30);
  console.log("user loaded");
  return { id, name: "Ada" };
}

async function loadOrders(userId: number): Promise<Order[]> {
  await sleep(10);
  console.log("orders loaded");
  return [
    { id: "o-1", userId, totalCents: 1299 },
    { id: "o-2", userId, totalCents: 450 },
  ];
}

const results = await Promise.all([loadUser(1), loadOrders(1)]);
//    ^? const results: [User, Order[]]
const [user, orders] = results;
const spent = orders.reduce((sum, o) => sum + o.totalCents, 0);
console.log(`${user.name}: ${orders.length} orders, $${(spent / 100).toFixed(2)}`);

import { setTimeout as sleep } from "node:timers/promises";

async function loadWeather(): Promise<string> {
  await sleep(10);
  return "12°C and cloudy";
}

async function loadNews(): Promise<string> {
  await sleep(20);
  throw new Error("news service timed out");
}

async function loadQuote(): Promise<string> {
  await sleep(15);
  return "Make it work, then make it fast.";
}

function show(name: string, result: PromiseSettledResult<string>): string {
  if (result.status === "fulfilled") {
    return `${name}: ${result.value}`;
    //                 ^? (parameter) result: PromiseFulfilledResult<string>
  }
  const reason = result.reason instanceof Error ? result.reason.message : String(result.reason);
  return `${name}: unavailable (${reason})`;
}

const [weather, news, quote] = await Promise.allSettled([loadWeather(), loadNews(), loadQuote()]);
console.log(show("weather", weather));
console.log(show("news", news));
console.log(show("quote", quote));

import { setTimeout as sleep } from "node:timers/promises";

async function fetchFrom(mirror: string, ms: number, up: boolean): Promise<string> {
  await sleep(ms);
  if (!up) {
    throw new Error(`${mirror} is down`);
  }
  return mirror;
}

function mirrors(): Promise<string>[] {
  return [fetchFrom("eu", 10, false), fetchFrom("us", 30, true), fetchFrom("asia", 50, true)];
}

try {
  const first = await Promise.race(mirrors());
  console.log(`race: ${first}`);
} catch (err) {
  console.log(`race failed: ${err instanceof Error ? err.message : String(err)}`);
}

const winner = await Promise.any(mirrors());
//    ^? const winner: string
console.log(`any: ${winner}`);

