import { setTimeout as sleep } from "node:timers/promises";

export type Page<T> = { items: T[]; nextCursor: string | null };

async function fetchFruit(cursor: string | null): Promise<Page<string>> {
  console.log(`fetch ${cursor ?? "first page"}`);
  await sleep(5);
  if (cursor === null) {
    return { items: ["apple", "banana"], nextCursor: "p2" };
  }
  if (cursor === "p2") {
    return { items: ["cherry"], nextCursor: "p3" };
  }
  return { items: ["damson", "elderberry"], nextCursor: null };
}

export async function* readAll(
  fetchPage: (cursor: string | null) => Promise<Page<string>>,
): AsyncGenerator<string> {
  let cursor: string | null = null;
  while (true) {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      yield item;
    }
    if (page.nextCursor === null) {
      return;
    }
    cursor = page.nextCursor;
  }
}

for await (const fruit of readAll(fetchFruit)) {
  console.log(fruit);
}
